using System;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Input;
using Microsoft.Win32;
namespace Configurator { public partial class MainWindow { private async void MenuDatabaseExportExcel_Click(object sender, RoutedEventArgs e) { if (!UserAuthorizationService.Require(Permission.ExportData)) return; var databaseName=_selectedDbName; if(string.IsNullOrWhiteSpace(databaseName)) databaseName=GetActiveDatabases().FirstOrDefault(); if(string.IsNullOrWhiteSpace(databaseName)){Configurator.Infrastructure.ModernDialog.Show("Сначала подключите и выберите базу данных.","Экспорт БД",MessageBoxButton.OK,MessageBoxImage.Information);return;} var d=new SaveFileDialog{Title="Экспорт выбранной БД в Excel",Filter="Excel workbook (*.xlsx)|*.xlsx",DefaultExt=".xlsx",FileName=$"{databaseName}_SchemaExport.xlsx",AddExtension=true}; if(d.ShowDialog(this)!=true)return; try{Mouse.OverrideCursor=Cursors.Wait; await DatabaseExcelExportService.ExportAsync(_connection.ToConnectionString(databaseName),d.FileName); Configurator.Infrastructure.ModernDialog.Show($"Экспорт завершён.\n\nБаза: {databaseName}\nФайл: {d.FileName}","Экспорт БД",MessageBoxButton.OK,MessageBoxImage.Information);}catch(Exception ex){Configurator.Infrastructure.ModernDialog.Show($"Не удалось экспортировать базу данных:\n\n{ex.Message}","Ошибка экспорта БД",MessageBoxButton.OK,MessageBoxImage.Error);}finally{Mouse.OverrideCursor=null;} } } }